    n = len(nums)
    if n == 0:
        return []
    lower = (">=", _fill(nums, pre))
    if nums[0] > 0:
        upper = Version(nums[0] + 1, 0, 0)
    elif n == 1:
        upper = Version(1, 0, 0)
    elif nums[1] > 0 or n == 2:
